#[test]
fn parser_self_checks_prefix_formulas_against_the_fixture_workbook() {
    let parsed = parse_master_list(master_list_path()).unwrap();

    assert_eq!(parsed.input_rows, 445);
    assert_eq!(parsed.equipment.len(), 445);
    assert!(parsed.errors.is_empty(), "{:#?}", parsed.errors);
    assert_eq!(parsed.prefix_checked_rows, 445);
}

#[test]
fn fixture_workbook_is_the_generated_synthetic_one() {
    use calamine::Reader;

    // Generated by rest/tests/fixtures/master-list.py: synthetic sheet names and no document properties (L4-F1).
    let workbook = calamine::open_workbook_auto(master_list_path()).unwrap();
    assert_eq!(
        workbook.sheet_names(),
        ["가상물류 지게차 Master list", "예비 및 여유차량"]
    );
    let bytes = std::fs::read(master_list_path()).unwrap();
    assert!(
        !bytes.windows(17).any(|w| w == b"docProps/core.xml"),
        "the fixture carries no document properties"
    );
}
